use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.split('\n');
    let n: usize = lines
        .next()
        .unwrap_or("")
        .trim_end_matches('\r')
        .trim()
        .parse()
        .unwrap_or(0);

    if n == 0 {
        println!();
        return;
    }

    let first = lines.next().unwrap_or("").trim_end_matches('\r');
    let mut prefix_len = first.len();

    for _ in 1..n {
        let current = lines.next().unwrap_or("").trim_end_matches('\r');
        prefix_len = first.as_bytes()[..prefix_len]
            .iter()
            .zip(current.as_bytes())
            .take_while(|(a, b)| a == b)
            .count();
    }

    println!("{}", &first[..prefix_len]);
}

