    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().trim().parse().unwrap();
    let mut seen = HashSet::with_capacity(n);
    let mut retained = Vec::new();

    for word in lines.take(n) {
        if seen.insert(word) {
            retained.push(word);
