import sys


def main() -> None:
    input_stream = sys.stdin
    count = int(input_stream.readline())

    if count == 0:
        print()
        return

    start, end = map(int, input_stream.readline().split())
    merged = []

    for _ in range(count - 1):
        next_start, next_end = map(int, input_stream.readline().split())
        if next_start <= end:
            end = max(end, next_end)
        else:
            merged.append((start, end))
            start, end = next_start, next_end

    merged.append((start, end))
    print(",".join(f"{left}:{right}" for left, right in merged))


if __name__ == "__main__":
    main()

