use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut numbers = input.split_whitespace();

    let n: usize = numbers.next().unwrap().parse().unwrap();
    let k: usize = numbers.next().unwrap().parse().unwrap();
    let values: Vec<i128> = numbers
        .take(n)
        .map(|value| value.parse().unwrap())
        .collect();

    let mut sum: i128 = values[..k].iter().sum();
    let mut output = sum.to_string();

    for end in k..n {
        sum += values[end] - values[end - k];
        output.push(',');
        output.push_str(&sum.to_string());
    }

    println!("{output}");
}

