import sys


def main() -> None:
    lines = sys.stdin.buffer
    count_line = lines.readline()
    if not count_line:
        return

    count = int(count_line)
    if count == 0:
        print()
        return

    start, end = map(int, lines.readline().split())
    merged = []

    for _ in range(count - 1):
        next_start, next_end = map(int, lines.readline().split())
        if next_start <= end:
