    for _ in 0..n {
        let start: i64 = values.next().unwrap().parse().unwrap();
        let end: i64 = values.next().unwrap().parse().unwrap();

        if let Some(last) = merged.last_mut() {
            if start <= last.1 {
                last.1 = last.1.max(end);
                continue;
            }
        }
        merged.push((start, end));
    }

    let output = merged
        .iter()
        .map(|(start, end)| format!("{start}:{end}"))
        .collect::<Vec<_>>()
        .join(",");
    println!("{output}");
}

