import sys


def main() -> None:
    first_line = sys.stdin.buffer.readline()
    if not first_line:
        return

    count = int(first_line)
    if count == 0:
        print()
        return

    prefix = sys.stdin.buffer.readline().rstrip(b"\r\n")
    for _ in range(count - 1):
        word = sys.stdin.buffer.readline().rstrip(b"\r\n")
        limit = min(len(prefix), len(word))
        index = 0
        while index < limit and prefix[index] == word[index]:
            index += 1
        prefix = prefix[:index]

    sys.stdout.buffer.write(prefix + b"\n")


if __name__ == "__main__":
    main()

