        .map(|_| fields.next().unwrap().parse().unwrap())
        .collect();

    let mut sum: i128 = values[..k].iter().sum();
    let mut sums = Vec::with_capacity(n - k + 1);
    sums.push(sum.to_string());

    for end in k..n {
