import sys


def main() -> None:
    lines = sys.stdin.buffer
    first = lines.readline()
    if not first:
        return

    count = int(first)
    totals: dict[bytes, int] = {}
    for _ in range(count):
        name = lines.readline().rstrip(b"\r\n")
        totals[name] = totals.get(name, 0) + 1

    if totals:
        winner, votes = min(totals.items(), key=lambda item: (-item[1], item[0]))
        sys.stdout.buffer.write(winner + b" " + str(votes).encode() + b"\n")


if __name__ == "__main__":
    main()

