fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap_or("0").parse().unwrap();

    if n == 0 {
        println!("0");
        return;
    }

    let mut previous: i128 = values.next().unwrap().parse().unwrap();
    let mut current_run = 1usize;
    let mut longest_run = 1usize;

    for _ in 1..n {
        let value: i128 = values.next().unwrap().parse().unwrap();
        if value > previous {
            current_run += 1;
            longest_run = longest_run.max(current_run);
        } else {
            current_run = 1;
        }
        previous = value;
    }

    println!("{longest_run}");
}

