import sys


def main() -> None:
    lines = sys.stdin.buffer
    count = int(lines.readline())

    if count == 0:
        print(0)
        return

    previous = int(lines.readline())
    current_length = 1
    longest_length = 1

    for _ in range(count - 1):
        value = int(lines.readline())
        if value > previous:
            current_length += 1
            if current_length > longest_length:
                longest_length = current_length
        else:
            current_length = 1
        previous = value

    print(longest_length)


if __name__ == "__main__":
    main()

