import sys


def main() -> None:
    input_stream = sys.stdin.buffer
    count = int(input_stream.readline())

    if count == 0:
        print()
        return

    current_start, current_end = map(int, input_stream.readline().split())
    merged = []

    for _ in range(count - 1):
        start, end = map(int, input_stream.readline().split())
        if start <= current_end:
            if end > current_end:
                current_end = end
        else:
            merged.append(f"{current_start}:{current_end}")
            current_start, current_end = start, end

    merged.append(f"{current_start}:{current_end}")
    print(",".join(merged))


if __name__ == "__main__":
    main()

