use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();

    if n == 0 {
        println!("0");
        return;
    }

    let mut previous: i64 = values.next().unwrap().parse().unwrap();
    let mut current = 1usize;
    let mut longest = 1usize;

    for _ in 1..n {
        let value: i64 = values.next().unwrap().parse().unwrap();
        if value > previous {
            current += 1;
            longest = longest.max(current);
        } else {
            current = 1;
        }
        previous = value;
    }

    println!("{longest}");
}

source_texts.longest_common_prefix:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().trim().parse().unwrap();

    if n == 0 {
        println!();
        return;
    }

    let first = lines.next().unwrap_or("").trim_end_matches('\r');
    let mut prefix_len = first.len();

    for _ in 1..n {
        let line = lines.next().unwrap_or("").trim_end_matches('\r');
        prefix_len = first.as_bytes()[..prefix_len]
            .iter()
            .zip(line.as_bytes())
            .take_while(|(a, b)| a == b)
            .count();
    }

    println!("{}", &first[..prefix_len]);
}

source_texts.stable_word_deduplication:
use std::collections::HashSet;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut words = input.split_whitespace();
    let n: usize = words.next().unwrap().parse().unwrap();
    let mut seen = HashSet::new();
    let mut retained = Vec::new();

    for _ in 0..n {
        let word = words.next().unwrap();
        if seen.insert(word) {
            retained.push(word);
        }
    }

    println!("{}", retained.join("|"));
}

