source_texts.moving_window_sums:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut parts = input.split_whitespace();

    let n: usize = parts.next().unwrap().parse().unwrap();
    let k: usize = parts.next().unwrap().parse().unwrap();
    let values: Vec<i128> = parts
        .take(n)
        .map(|value| value.parse().unwrap())
        .collect();

    let mut sum: i128 = values[..k].iter().sum();
    let mut sums = Vec::with_capacity(n - k + 1);
    sums.push(sum.to_string());

    for index in k..n {
        sum += values[index] - values[index - k];
        sums.push(sum.to_string());
    }

    println!("{}", sums.join(","));
}

source_texts.rotate_words_left:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();

    let n: usize = lines.next().unwrap().trim().parse().unwrap();
    let k: usize = lines.next().unwrap().trim().parse().unwrap();
    let words: Vec<&str> = lines.take(n).collect();

    if n == 0 {
        println!();
        return;
    }

    let shift = k % n;
    let rotated = words[shift..]
        .iter()
        .chain(words[..shift].iter())
        .copied()
        .collect::<Vec<_>>();
    println!("{}", rotated.join("|"));
}

