use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();

    if n == 0 {
        println!("0");
        return;
    }

    let mut previous: i128 = values.next().unwrap().parse().unwrap();
    let mut current = 1usize;
    let mut longest = 1usize;

    for value in values.take(n - 1) {
        let value: i128 = value.parse().unwrap();
        if value > previous {
            current += 1;
            longest = longest.max(current);
        } else {
            current = 1;
        }
        previous = value;
    }

    println!("{longest}");
}

source_texts.moving_window_sums:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let k: usize = tokens.next().unwrap().parse().unwrap();
    let values: Vec<i128> = tokens
        .take(n)
        .map(|value| value.parse().unwrap())
        .collect();

    let mut sum: i128 = values[..k].iter().sum();
    let mut output = sum.to_string();

    for index in k..n {
        sum += values[index] - values[index - k];
        output.push(',');
        output.push_str(&sum.to_string());
    }

    println!("{output}");
}

