to main:
    let n_input be ask for a number ""
    let n be value of n_input
    let lines be an empty list of text
    repeat n times:
        add ask "" to lines
    if n is 0:
        say ""
    otherwise:
        let prefix be item 1 of lines
        for each line_number from 2 to n:
            let line be item line_number of lines
            let limit be length of prefix
            if length of line is less than limit:
                set limit to length of line
            let matching be 0
            if limit is more than 0:
                for each cursor from 1 to limit:
                    if item cursor of prefix is item cursor of line:
                        if matching is cursor - 1:
                            set matching to cursor
            let prefix_parts be an empty list of text
            if matching is more than 0:
                for each cursor from 1 to matching:
                    add item cursor of prefix to prefix_parts
            set prefix to prefix_parts joined with ""
        say prefix

