import sys


def main():
    lines = sys.stdin.read().splitlines()
    n = int(lines[0])
    values = [int(value) for value in lines[1:1 + n]]
    if not values:
        print(0)
        return
    longest = current = 1
    for previous, value in zip(values, values[1:]):
        if value > previous:
            current += 1
            longest = max(longest, current)
        else:
            current = 1
    print(longest)


if __name__ == "__main__":
    main()

