use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let line = input.lines().next().unwrap_or("");
    let mut characters = line.chars();
    let Some(mut current) = characters.next() else {
        println!();
        return;
    };

    let mut count = 1usize;
    let mut groups = Vec::new();
    for character in characters {
        if character == current {
            count += 1;
        } else {
            groups.push(format!("{current}:{count}"));
            current = character;
            count = 1;
        }
    }
    groups.push(format!("{current}:{count}"));
    println!("{}", groups.join(","));
}

source_texts.plurality_winner:
use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().trim().parse().unwrap();
    let mut counts = BTreeMap::new();

    for name in lines.take(n) {
        *counts.entry(name).or_insert(0usize) += 1;
    }

    if let Some((name, count)) = counts.iter().max_by(|left, right| {
        left.1.cmp(right.1).then_with(|| right.0.cmp(left.0))
    }) {
        println!("{name} {count}");
    }
}

