use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();

    if n == 0 {
        println!("0");
        return;
    }

    let mut previous: i128 = values.next().unwrap().parse().unwrap();
    let mut current = 1usize;
    let mut longest = 1usize;
    for value in values.take(n - 1) {
        let number: i128 = value.parse().unwrap();
        if number > previous {
            current += 1;
            longest = longest.max(current);
        } else {
            current = 1;
        }
        previous = number;
    }
    println!("{longest}");
}

sources.merge_sorted_intervals:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();

    if n == 0 {
        println!();
        return;
    }

    let mut start: i128 = values.next().unwrap().parse().unwrap();
    let mut end: i128 = values.next().unwrap().parse().unwrap();
    let mut merged = Vec::new();

    for _ in 1..n {
        let next_start: i128 = values.next().unwrap().parse().unwrap();
        let next_end: i128 = values.next().unwrap().parse().unwrap();
        if next_start <= end {
            end = end.max(next_end);
        } else {
            merged.push(format!("{start}:{end}"));
            start = next_start;
            end = next_end;
        }
    }
    merged.push(format!("{start}:{end}"));
    println!("{}", merged.join(","));
}

sources.moving_window_sums:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();
    let k: usize = values.next().unwrap().parse().unwrap();
    let numbers: Vec<i128> = values.take(n).map(|value| value.parse().unwrap()).collect();

    let mut sum: i128 = numbers[..k].iter().sum();
    let mut sums = Vec::with_capacity(n - k + 1);
    sums.push(sum.to_string());
    for index in k..n {
        sum += numbers[index] - numbers[index - k];
        sums.push(sum.to_string());
    }
    println!("{}", sums.join(","));
}

